@code {
    private AppointmentFormModel Model { get; set; } = new();
    private bool showStep2;
    private bool availabilityChecked;
    private bool bookingConfirmed;
    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private Dictionary<string, string> serverErrors = new();
    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields manually
        editContext = new EditContext(Model);
        var validationResults = new List<ValidationResult>();
        var isValid = Validator.TryValidateProperty(Model.PatientName,
            new ValidationContext(Model) { MemberName = nameof(Model.PatientName) }, validationResults);
        isValid &= Validator.TryValidateProperty(Model.Email,
            new ValidationContext(Model) { MemberName = nameof(Model.Email) }, validationResults);
        isValid &= Validator.TryValidateProperty(Model.Phone,
            new ValidationContext(Model) { MemberName = nameof(Model.Phone) }, validationResults);
        isValid &= Validator.TryValidateProperty(Model.InsuranceProvider,
            new ValidationContext(Model) { MemberName = nameof(Model.InsuranceProvider) }, validationResults);

        if (isValid)
        {
            showStep2 = true;
        }
        else
        {
            // Trigger EditForm validation display by notifying field changes
            editContext.NotifyValidationStateChanged();
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        serverErrors.Clear();

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        // Require step 2 fields before checking
        if (string.IsNullOrEmpty(Model.Doctor) || !Model.AppointmentDate.HasValue ||
            string.IsNullOrEmpty(Model.TimeSlot) || string.IsNullOrEmpty(Model.ReasonForVisit))
        {
            return;
        }

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email ?? "",
            Model.InsuranceProvider ?? "",
            Model.Doctor,
            Model.TimeSlot);

        if (errors.Count > 0)
        {
            serverErrors = errors;
        }
        else
        {
            availabilityChecked = true;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityChecked && serverErrors.Count == 0)
        {
            bookingConfirmed = true;
        }
    }

